provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "kinesis_analytics_role" {
  name = "kinesis-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kinesis_analytics_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonKinesisAnalyticsServiceRolePolicy"
  role       = aws_iam_role.kinesis_analytics_role.name
}

resource "aws_s3_bucket" "kinesis_analytics_input_bucket" {
  bucket = "kinesis-analytics-input-bucket-${var.random_suffix}"
  acl    = "private"
}

resource "aws_s3_bucket_policy" "kinesis_analytics_input_bucket_policy" {
  bucket = aws_s3_bucket.kinesis_analytics_input_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
        Resource = "${aws_s3_bucket.kinesis_analytics_input_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_kinesis_stream" "kinesis_analytics_input_stream" {
  name        = "kinesis-analytics-input-stream-${var.random_suffix}"
  shard_count = 1
}

resource "aws_kinesis_analytics_application" "kinesis_analytics_app" {
  name = "my_kinesis_analytics_app"

  inputs {
    name_prefix = "input-prefix-${var.random_suffix}"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.kinesis_analytics_input_stream.arn
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }

    parallelism {
      count = 1
    }

    schema {
      record_columns {
        mapping = "$.data"
        name    = "data"
        sql_type = "VARCHAR(8)"
      }

      record_encoding = "UTF-8"

      record_format {
        mapping_parameters {
          json {
            record_row_path = "$"
          }
        }
      }
    }
  }

  outputs {
    name = "output-${var.random_suffix}"

    schema {
      record_format_type = "JSON"
    }

    kinesis_firehose {
      delivery_stream_arn = aws_kinesis_firehose_delivery_stream.kinesis_analytics_output_stream.arn
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics_log_stream.arn
    role_arn     = aws_iam_role.kinesis_analytics_role.arn
  }
}

resource "aws_cloudwatch_log_group" "kinesis_analytics_log_group" {
  name = "kinesis-analytics-log-group-${var.random_suffix}"
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics_log_stream" {
  name        = "kinesis-analytics-log-stream-${var.random_suffix}"
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics_log_group.name
}

resource "aws_kinesis_firehose_delivery_stream" "kinesis_analytics_output_stream" {
  name = "kinesis-analytics-output-stream-${var.random_suffix}"

  destination = "extended_s3"

  extended_s3_configuration {
    bucket_arn = aws_s3_bucket.kinesis_analytics_output_bucket.arn
    role_arn   = aws_iam_role.kinesis_analytics_role.arn
  }
}

variable "random_suffix" {
  default = "12345"
}
