provider "aws" {
  region = "us-east-1"
}

# Define an IAM policy document for assuming a role by EKS pods
data "aws_iam_policy_document" "assume_role" {
  statement {
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["pods.eks.amazonaws.com"]
    }
    actions = ["sts:AssumeRole", "sts:TagSession"]
  }
}

# Create an IAM role using the assume_role policy
resource "aws_iam_role" "example" {
  name = "eks-pod-identity-example"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

# Attach a policy for S3 read-only access to this role
resource "aws_iam_role_policy_attachment" "example_s3" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
  role = aws_iam_role.example.name
}

# Define an EKS cluster with pod identity management
resource "aws_eks_cluster" "example" {
  name = "example-cluster"
  role_arn = aws_iam_role.example.arn
  version = "1.26"

  # Configure VPC settings
  vpc_config {
    endpoint_private_access = true
    endpoint_public_access = true
    subnet_ids = [
      "subnet-12345678",  # Replace with actual subnet IDs
      "subnet-23456789",
      "subnet-34567890",
    ]
  }

  # Configure pod identity association
  pod_identity_associations {
    cluster_name = aws_eks_cluster.example.name
    namespace = "example"
    service_account = "example-sa"
    role_arn = aws_iam_role.example.arn
  }
}
