  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true
}

resource "aws_subnet" "memcached_subnet" {
  vpc_id = aws_vpc.memcached_vpc.id
  cidr_block = "10.0.0.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "memcached_sg" {
  vpc_id = aws_vpc.memcached_vpc.id
  description = "Allow Memcached traffic"
  ingress {
    from_port   = 11211
    to_port     = 11211
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "memcached_instance" {
  ami           = "ami-0c55b159cbfafe1f0" # Example AMI for t3.micro
  instance_type = "t3.micro"
  subnet_id      = aws_subnet.memcached_subnet.id
  security_groups = [aws_security_group.memcached_sg.id]
  tags = {
    Name = "memcached-instance"
  }
}

resource "aws_elasticache_cluster" "memcached_cluster" {
  cluster_id = "memcached-cluster"
  engine      = "memcached"
  engine_version = "1.6.15"
  num_cache_nodes = 1
  node_type = "cache.t3.micro"
  subnet_group_name = aws_subnet.memcached_subnet.id
  security_group_ids = [aws_security_group.memcached_sg.id]
  tags = {
    Name = "memcached-cluster"
  }
}
```

This Terraform program creates a basic Memcached cluster using AWS services. It includes a VPC, subnet, security group, EC2 instance, and Elasticache cluster. The configuration is set up to allow inbound traffic on port 11211 for Memcached. The default values for the AMI and instance type are provided, and the subnet and security group IDs are referenced directly.

