provider "aws" {
  region = "us-west-2"
}

variable "environment" {
  description = "The environment for the S3 bucket and DynamoDB table"
  default     = "dev"
}

resource "aws_s3_bucket" "example_table_insights_bucket" {
  bucket = "example-table-insights-bucket-${var.environment}"
  acl     = "private"
}

resource "aws_dynamodb_table" "example_table_insights_table" {
  name           = "ExampleTableName"
  billing_mode   = "PAY_PER_REQUEST"
  read_capacity  = 5
  write_capacity = 5

  attribute {
    name = "id"
    type = "S"
  }

  global_secondary_index {
    name           = "ContributorIndex"
    hash_key       = "ContributorID"
    projection_type = "ALL"
  }
}

resource "aws_lambda_function" "example_table_insights_lambda" {
  function_name = "ExampleTableInsightsLambda"
  role          = aws_iam_role.example_table_insights_lambda.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  timeout       = 30

  code {
    s3_bucket = aws_s3_bucket.example_table_insights_bucket.bucket
    s3_key    = "lambda-function.zip"
  }

  environment {
    variables = {
      TABLE_NAME = aws_dynamodb_table.example_table_insights_table.name
    }
  }

  vpc_config {
    subnet_ids = ["subnet-12345678", "subnet-87654321"]
    security_group_ids = ["sg-12345678"]
  }
}

resource "aws_cloudwatch_event_rule" "example_table_insights_event_rule" {
  name        = "ExampleTableInsightsEventRule"
  schedule_expression = "rate(1 minute)"
  state        = "ENABLED"
}

resource "aws_cloudwatch_event_target" "example_table_insights_event_target" {
  arn         = aws_lambda_function.example_table_insights_lambda.arn
  rule        = aws_cloudwatch_event_rule.example_table_insights_event_rule.name
}

resource "aws_iam_role" "example_table_insights_lambda" {
  name = "ExampleTableInsightsLambdaRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "example_table_insights_lambda_policy" {
