```hcl
provider "aws" {
  region = "us-east-1"
}

variable "msk_cluster_name" {
  default = "my-msk-cluster"
}

variable "kafka_version" {
  default = "2.7.1"
}

variable "number_of_broker_nodes" {
  default = 3
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = var.msk_cluster_name
  kafka_version = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes

  broker_node_group_info {
    instance_type = "kafka.m5.4xlarge"
    client_subnets = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
    security_groups = ["sg-12345678"]

    storage_info {
      ebs_storage_info {
        provisioned_throughput {
          enabled = true
          volume_throughput = 250
        }
        volume_size = 1000
      }
    }
  }

  logging_info {
    broker_logs {
      enabled = true
      firehose {
        delivery_stream_name = aws_kinesis_firehose_delivery_stream.msk_firehose.name
      }
    }
  }
}

resource "aws_kinesis_firehose_delivery_stream" "msk_firehose" {
  name = var.msk_cluster_name

  destination = "extended_s3"

  extended_s3_configuration {
    bucket_arn = aws_s3_bucket.msk_firehose_bucket.arn
    role_arn = aws_iam_role.msk_firehose_role.arn

    buffering_interval = 60
    buffering_size = 1024
    compression_format = "GZIP"
    custom_time_zone = "UTC"
    error_output_prefix = "error/"
    file_extension = "csv"
    kms_key_arn = aws_kms_key.msk_firehose_key.arn
    prefix = "data/"
    s3_backup_mode = "Enabled"
  }
}

resource "aws_s3_bucket" "msk_firehose_bucket" {
  bucket = var.msk_cluster_name
  acl = "private"
}

resource "aws_iam_role" "msk_firehose_role" {
  name = var.msk_cluster_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_kms_key" "msk_firehose_key" {
  description = "MSK Firehose KMS Key"
}
```

