provider "aws" {
  region = "us-west-2"
}

variable "cluster_name" {
  default = "my-msk-cluster"
}

variable "kafka_version" {
  default = "2.8.1"
}

variable "number_of_broker_nodes" {
  default = 3
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes

  enhanced_monitoring = "DEFAULT"

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
    instance_type   = "t3.micro"
    security_groups = ["sg-12345678"]

    az_distribution = "DEFAULT"
  }

  client_authentication {
    unauthenticated = true
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-west-2:123456789012:key/12345678-1234-1234-1234-123456789012"
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = true
        log_group = "/aws/msk/my-msk-cluster"
      }
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled = true
      }
    }
  }

  timeouts {
    create = "60m"
    delete = "60m"
    update = "60m"
  }
}
