### Description
This Terraform program creates a PostgreSQL instance within an existing VPC and subnet group. It includes necessary IAM roles and configurations to ensure secure access to the database.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"
}

# Define the VPC
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

# Define the subnet
resource "aws_subnet" "example" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.0.0/24"
  availability_zone = "us-west-2a"
}

# Define the security group
resource "aws_security_group" "example" {
  name        = "db-sg"
  description = "Allow inbound PostgreSQL traffic"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Define the IAM role for the database instance
resource "aws_iam_role" "db_instance_role" {
  name = "db-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "db_instance_policy_attachment" {
  role       = aws_iam_role.db_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSServiceRoleForRDS"
}

# Define the PostgreSQL instance
resource "aws_db_instance" "example" {
  allocated_storage       = 20
  engine                  = "postgres"
  engine_version          = "13.6"
  instance_class           = "db.t3.micro"
  db_subnet_group_name   = aws_db_subnet.example.id
  vpc_security_group_ids = [aws_security_group.example.id]
  skip_final_snapshot     = true
  iam_roles               = [aws_iam_role.db_instance_role.arn]
}
```

### Explanation
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **VPC and Subnet**: A VPC and a subnet are created within the specified CIDR block and availability zone.
- **Security Group**: A security group is defined to allow inbound PostgreSQL traffic on port 5432.
- **IAM Role**: An IAM role is created to manage the database instance. This role assumes the `AWSServiceRoleForRDS` policy, which allows the instance to interact with Amazon RDS.
- **Database Instance**: The PostgreSQL instance is created within the specified VPC, subnet, and security group. It uses the IAM role for authentication and is configured to skip final snapshots.

