provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name for the S3 bucket"
  default     = "dev"
}

resource "aws_kms_key" "game_scores_kms_key" {
  description = "KMS key for server-side encryption of DynamoDB table"
}

resource "aws_s3_bucket" "game_scores_bucket" {
  bucket = "game-scores-bucket-${var.environment}"
  acl     = "private"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.game_scores_kms_key.arn
        sse_algorithm    = "aws:kms"
      }
    }
  }
}

resource "aws_dynamodb_table" "game_scores" {
  name           = "GameScores"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "UserId"
  range_key      = "GameTitle"
  read_capacity  = 10
  write_capacity = 10

  attribute {
    name = "UserId"
    type = "S"
  }

  attribute {
    name = "GameTitle"
    type = "S"
  }

  attribute {
    name = "TopScore"
    type = "N"
  }

  ttl {
    attribute_name = "TimeToExist"
    enabled        = true
  }

  global_secondary_index {
    name          = "GameTitleIndex"
    hash_key      = "GameTitle"
    range_key      = "TopScore"
    write_capacity = 10
    read_capacity  = 10
    projection_type = "INCLUDE"
    non_key_attributes = ["UserId"]
  }
}
```

