provider "aws" {
  region = "us-east-1"  # Default region for S3 website hosting
}

variable "bucket_name_prefix" {
  description = "Prefix for the S3 bucket name"
  default     = "my-website-images-bucket"
}

variable "random_suffix_length" {
  description = "Length of the random suffix for the S3 bucket name"
  default     = 8
}

resource "random_string" "random_suffix" {
  length = var.random_suffix_length
  special = false
  upper = false
  lower = false
}

resource "aws_s3_bucket" "website_images_bucket" {
  bucket = "${var.bucket_name_prefix}-${random_string.random_suffix.result}"
  acl    = "public-read"

  tags = {
    Name = "Website Images Bucket"
  }
}

resource "aws_s3_bucket_website_configuration" "website_images_bucket_website_config" {
  bucket = aws_s3_bucket.website_images_bucket.bucket

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "error.html"
  }
}
```

This Terraform program creates an AWS S3 bucket to store images for a website. It includes a random suffix to ensure uniqueness, and it configures the bucket for website hosting with an index document and an error document. The program uses the `hashicorp/aws` provider version 5.75.0 and Terraform version 1.9.8.

