```hcl
provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zone" "main" {
  state = "available"
}

resource "aws_s3_bucket" "autograder_results" {
  bucket = "cs-class-autograder-results-${var.student_id}"
  acl     = "private"

  tags = {
    Name        = "CS Class Autograder Results"
    Environment = "Development"
  }
}

resource "aws_codebuild_project" "cs_class_autograder" {
  name          = "cs-class-autograder-${var.student_id}"
  service_role  = aws_iam_role.codebuild_service_role.arn
  badge_enabled = true

  artifacts {
    type = "S3"
    location = aws_s3_bucket.autograder_results.bucket
  }

  environment {
    type           = "LINUX_CONTAINER"
    image          = "aws/codebuild/standard:5.0"
    compute_type   = "BUILD_GENERAL1_SMALL"
    privileged_mode = true
  }

  source {
    type = "GITHUB"
    location = "https://github.com/${var.github_username}/cs-class-autograder.git"
    report_build_status = true
  }

  vpc_config {
    vpc_id     = aws_vpc.main.id
    subnets     = aws_subnet.public.*.id
    security_group_ids = aws_security_group.codebuild_sg.id
  }

  logging {
    s3_logs {
      bucket = aws_s3_bucket.autograder_results.bucket
      prefix = "logs/"
    }
  }

  cache {
    type = "LOCAL"
    location = "/tmp/cache"
    modes = ["LOCAL_SOURCE_CACHE", "LOCAL_DOCKER_LAYER_CACHE"]
  }
}

resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role-${var.student_id}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_service_role_policy" {
  role       = aws_iam_role.codebuild_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildServiceRolePolicy"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "CS Class VPC"
  }
}

resource "aws_subnet" "public" {
  count = 2

  cidr_block          = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zone.main.name[count.index]

  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "Public Subnet ${count.index + 1}"
    Environment = "Development"
  }
}

resource "aws_security_group" "codebuild_sg" {
  name        = "codebuild-sg-${var.student_id}"
  description = "Security group for the CS Class Autograder CodeBuild project"

  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "CodeBuild Security Group"
    Environment = "Development"
  }
}

variable "student_id" {
  description = "Unique identifier for the student"
  default     = "student123"
}

variable "github_username" {
  description = "GitHub username of the student"
  default     = "studentusername"
}
```

