  name = "autograder-project"
  service_role = aws_iam_role.autograder_role.arn

  source {
    type = "GitHub"
    location = "https://github.com/username/repository.git"
    git_clone_depth = 1
    insecure_ssl = true
    report_build_status = true
  }

  artifacts {
    type = "S3"
    location = aws_s3_bucket.autograder_results_bucket.bucket
    name = "autograder-results"
  }

  environment {
    type = "LINUX_CONTAINER"
    image = "aws/codebuild/standard:5.0"
    compute_type = "BUILD_GENERAL1_SMALL"
    privileged_mode = false
  }

  vpc_config {
    security_group_ids = [aws_security_group.autograder_sg.id]
    subnets = [aws_subnet.autograder_subnet.id]
    vpc_id = aws_vpc.autograder_vpc.id
  }
