  region = "us-east-1"
}

variable "bucket_name" {
  default = "cat-pictures-bucket-${random_string.random_suffix.result}"
}

variable "lambda_function_name" {
  default = "cat-picture-generator"
}

variable "lambda_handler" {
  default = "index.handler"
}

variable "lambda_runtime" {
  default = "python3.8"
}

variable "lambda_memory_size" {
  default = 128
}

variable "lambda_timeout" {
  default = 30
}

resource "random_string" "random_suffix" {
  length = 8
  special = false
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = var.bucket_name
  acl    = "private"

  tags = {
    Name = "Cat Pictures Bucket"
  }
}

resource "aws_lambda_function" "cat_picture_generator" {
  function_name = var.lambda_function_name
  role          = aws_iam_role.lambda_execution_role.arn

  handler       = var.lambda_handler
  runtime       = var.lambda_runtime
  timeout       = var.lambda_timeout
  memory_size   = var.lambda_memory_size

  code {
    s3_bucket = aws_s3_bucket.cat_pictures_bucket.bucket
    s3_key    = "cat_picture_generator.zip"
  }

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }

  depends_on = [aws_s3_bucket.cat_pictures_bucket]
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role-${random_string.random_suffix.result}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_execution_role_policy" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_api_gateway_rest_api" "cat_picture_api" {
  name = "cat-picture-api"

  binary_media_types = ["application/json"]
  description       = "API Gateway for cat picture functionality"
}

resource "aws_api_gateway_resource" "cat_picture_resource" {
  parent_id   = aws_api_gateway_rest_api.cat_picture_api.root_resource_id
  path_part   = "cat-pictures"
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
}

resource "aws_api_gateway_method" "cat_picture_method" {
  authorization         = "NONE"
  http_method           = "GET"
  resource_id            = aws_api_gateway_resource.cat_picture_resource.id
  rest_api_id            = aws_api_gateway_rest_api.cat_picture_api.id
  request_parameters = {
    "method.request.querystring.cat-id" = "false"
  }
}

resource "aws_api_gateway_integration" "cat_picture_integration" {
  http_method           = aws_api_gateway_method.cat_picture_method.http_method
  resource_id            = aws_api_gateway_method.cat_picture_method.resource_id
  rest_api_id            = aws_api_gateway_method.cat_picture_method.rest_api_id
  type                  = "AWS_PROXY"
  uri                   = "arn:aws:apigateway:${var.region}:lambda:path/2015-03-31/functions/${aws_lambda_function.cat_picture_generator.arn}/invocations"
  integration_http_method = "POST"
}

resource "aws_api_gateway_deployment" "cat_picture_deployment" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id

  triggers = {
    redeployment = "${random_string.random_suffix.result}"
  }
}

resource "aws_api_gateway_stage" "cat_picture_stage" {
  deployment_id = aws_api_gateway_deployment.cat_picture_deployment.id
  rest_api_id   = aws_api_gateway_rest_api.cat_picture_api.id
  stage_name   = "prod"
}
```

