  }
}

resource "aws_dynamodb_table" "cat_pictures_table" {
  name           = var.table_name
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "PictureID"
  range_key      = "Timestamp"
  read_capacity  = 5
  write_capacity = 5

  attribute {
    name = "PictureID"
    type = "S"
  }

  attribute {
    name = "Timestamp"
    type = "N"
  }

  tags = {
    Name = "Cat Pictures Table"
  }
}

resource "aws_lambda_function" "cat_picture_generator" {
  function_name = var.lambda_function_name
  role          = aws_iam_role.lambda_execution_role.arn

  runtime     = "python3.8"
  handler     = "cat_picture_generator.handler"
  source_code = file("cat_picture_generator.py")

  timeout     = 30
  memory_size = 128

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }

  tags = {
    Name = "Cat Pictures Generator"
  }
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "cat_picture_generator_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "Cat Pictures Lambda Role"
  }
}

resource "aws_iam_role_policy_attachment" "lambda_execution_role_policy" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_permission" "cat_picture_generator_permission" {
  statement_id = "AllowAPIGatewayInvoke"
  action       = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cat_picture_generator.function_name
  principal    = "apigateway.amazonaws.com"
}

resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name = "cat-pictures-api"

  tags = {
    Name = "Cat Pictures API"
  }
}

resource "aws_api_gateway_resource" "cat_pictures_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "cat-pictures"
}

resource "aws_api_gateway_method" "upload_cat_picture_method" {
  rest_api_id            = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.cat_pictures_resource.id
  http_method            = "POST"
  authorization          = "NONE"
  request_content_handling = "CONSUMED"

  request_models = {
    "application/json" = "com.amazonaws.apigateway.v2.models.UploadRequest"
  }

  request_parameters = {
    "method.request.path.picture-id" = "required"
  }

  integration {
    type              = "AWS_PROXY"
    integration_http_method = "POST"
    uri               = "arn:aws:apigateway:${data.aws_region.current.name}:lambda:path/2015-03-31/functions/${aws_lambda_function.cat_picture_generator.arn}/invocations"
    passthrough_behavior = "WHEN_NO_MATCH"
    content_handling   = "CONSUMED"
  }

  tags = {
    Name = "Upload Cat Picture Method"
  }
}

