  authorization          = "NONE"
  request_content_handling = "CONSUMED"

  integration {
    type              = "AWS_PROXY"
    integration_http_method = "GET"
    uri               = "arn:aws:apigateway:${data.aws_region.current.name}:lambda:path/2015-03-31/functions/${aws_lambda_function.cat_picture_generator.arn}/invocations"
    passthrough_behavior = "WHEN_NO_MATCH"
    content_handling   = "CONSUMED"
  }

  tags = {
    Name = "Get Random Cat Picture Method"
  }
}

resource "aws_api_gateway_deployment" "cat_pictures_api_deployment" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  stage_name  = "prod"

  deployment_description = "Production deployment of Cat Pictures API"
}

resource "aws_api_gateway_stage" "cat_pictures_api_stage" {
