```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "video-content-bucket-${random_string.random_suffix.result}"
  acl    = "private"

  tags = {
    Name        = "Video Content Bucket"
    Environment = "Production"
  }

  # Optional: Enable versioning for the bucket
  versioning {
    enabled = true
  }
}

resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  enabled             = true
  origin {
    domain_name = aws_s3_bucket.video_content_bucket.bucket_domain_name
    origin_id   = "video-content-bucket-origin"
  }

  default_cache_behavior {
    allowed_methods   = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "video-content-bucket-origin"
    viewer_protocol_policy = "allow-all"

    # Optional: Set up caching policies
    cache_policy_id = aws_cloudfront_cache_policy.standard_cache_policy.id

    # Optional: Set up origin request policies
    origin_request_policy_id = aws_cloudfront_origin_request_policy.standard_origin_request_policy.id

    # Optional: Set up response headers policies
    response_headers_policy_id = aws_cloudfront_response_headers_policy.standard_response_headers_policy.id
  }

  # Optional: Add custom error responses
  custom_error_response {
    error_code       = 404
    error_caching_min_ttl = 300
    response_code     = 404
    response_page_path = "/error.html"
  }

  # Optional: Add logging configuration
  logging_config {
    bucket = aws_s3_bucket.log_bucket.id
    prefix = "cloudfront-logs/"
  }

  # Optional: Restrict access to the distribution
  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations       = ["US", "CA", "UK"]
    }
  }

  # Optional: Use a custom SSL certificate
  viewer_certificate {
    ssl_support_method = "sni-only"
    acm_certificate_arn = "arn:aws:acm:us-east-1:123456789012:certificate/12345678-1234-1234-1234-123456789012"
  }

  # Optional: Enable real-time logs
  real_time_log_config_arn = aws_cloudfront_real_time_log_config.real_time_log_config.arn
}

resource "aws_s3_bucket" "log_bucket" {
  bucket = "video-streaming-distribution-logs-${random_string.random_suffix.result}"
  acl    = "private"

  tags = {
    Name        = "Video Streaming Distribution Logs"
    Environment = "Production"
  }
}

resource "aws_cloudfront_cache_policy" "standard_cache_policy" {
  name = "Standard Cache Policy"

  default_ttl        = 3600
  max_ttl          = 86400
  min_ttl          = 0
  parameters_included = [
    "Accept",
    "Accept-Language",
    "Cache-Control",
    "Content-Type",
    "Date",
    "ETag",
    "Expires",
    "If-Match",
    "If-Modified-Since",
    "If-None-Match",
    "If-Unmodified-Since",
    "Last-Modified",
    "Origin",
    "Referer",
    "User-Agent",
    "X-Amz-Cf-Id",
    "X-Amz-Cf-Viewer-Country",
    "X-Amzn-Trace-Id",
    "X-Forwarded-For",
    "X-Forwarded-Proto",
  ]

  query_strings_cache {
    query_string_behavior = "all"
  }

  cookies_cache {
    cookies_behavior = "all"
  }
}

resource "aws_cloudfront_origin_request_policy" "standard_origin_request_policy" {
  name = "Standard Origin Request Policy"

  cookies_config {
    cookie_behavior = "none"
  }

  query_strings_config {
    query_string_behavior = "none"
  }
}

resource "aws_cloudfront_response_headers_policy" "standard_response_headers_policy" {
  name = "Standard Response Headers Policy"

  security_headers_config {
    x_frame_options {
      frame_option = "DENY"
    }
    strict_transport_security {
      mode = "always"
      max_age = 31536000
      include_subdomains = true
      preload = true
    }
    content_security_policy {
      content_security_policy = "default-src 'self'; script-src 'self' https://cdn.example.com; style-src 'self' https://cdn.example.com; img-src 'self' https://cdn.example.com;"
      override = true
    }
  }
}

resource "aws_cloudfront_real_time_log_config" "real_time_log_config" {
  name        = "Video Streaming Distribution Real-Time Logs"
  sampling_rate = 100

  dynamic "field" {
    for_each = var.real_time_log_fields
    content {
      name = field.value.name
      type = field.value.type
    }
  }
}

variable "real_time_log_fields" {
