provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  default = "video-streaming-content-bucket-${random_string.bucket.id}"
}

variable "s3_bucket_acl" {
  default = "private"
}

variable "s3_bucket_tags" {
  default = {
    Name        = "Video Streaming Content Bucket"
    Environment = "Production"
  }
}

variable "s3_bucket_cors_rules" {
  default = [
    {
      allowed_methods   = ["GET", "HEAD", "PUT", "POST", "DELETE"]
      allowed_origins  = ["*"]
      allowed_headers  = ["*"]
      expose_headers  = ["ETag", "Last-Modified"]
      max_age_seconds = 3000
    }
  ]
}

variable "cloudfront_distribution_enabled" {
  default = true
}

variable "cloudfront_distribution_comment" {
  default = "Video Streaming Distribution"
}

variable "cloudfront_distribution_price_class" {
  default = "PriceClass_100"
}

variable "cloudfront_distribution_trusted_key_groups" {
  default = ["tkg-1234567890abcdef"]
}

variable "cloudfront_distribution_trusted_signers" {
  default = ["signer-1234567890abcdef"]
}

variable "route53_zone_name" {
  default = "example.com"
}

variable "route53_zone_tags" {
  default = {
    Name        = "Video Streaming Zone"
    Environment = "Production"
  }
}

variable "route53_record_name" {
  default = "www"
}

variable "route53_record_type" {
  default = "A"
}

variable "route53_record_zone_id" {
  default = aws_route53_zone.video_streaming_zone.zone_id
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = var.bucket_name
  acl     = var.s3_bucket_acl

  tags = var.s3_bucket_tags

  # Enable CORS for the S3 bucket
  cors_rule {
    allowed_methods   = var.s3_bucket_cors_rules[0].allowed_methods
    allowed_origins  = var.s3_bucket_cors_rules[0].allowed_origins
    allowed_headers  = var.s3_bucket_cors_rules[0].allowed_headers
    expose_headers  = var.s3_bucket_cors_rules[0].expose_headers
    max_age_seconds = var.s3_bucket_cors_rules[0].max_age_seconds
  }
}

resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  enabled = var.cloudfront_distribution_enabled

  origin {
    domain_name = aws_s3_bucket.video_content_bucket.bucket_domain_name
    origin_id   = "video-content-origin"
  }

  default_cache_behavior {
    allowed_methods   = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD", "OPTIONS"]
    target_origin_id = "video-content-origin"
    viewer_protocol_policy = "allow-all"

    # Set up caching for the video content
    default_ttl  = 3600
    max_ttl    = 86400
    min_ttl    = 60
  }

  # Enable logging for the CloudFront distribution
  logging_config {
    bucket = "logs-video-streaming-bucket-${random_string.logs.id}"
    prefix = "cloudfront-logs/"
  }

  # Set up a custom error response for 404 errors
  custom_error_response {
    error_code = 404
    error_caching_min_ttl = 300
    response_code = 404
    response_page_path = "/404.html"
  }

  # Set up a default root object
  default_root_object = "index.html"

  # Set up a comment for the CloudFront distribution
  comment = var.cloudfront_distribution_comment

  # Set up a price class
  price_class = var.cloudfront_distribution_price_class

  # Set up a trusted key group
  trusted_key_groups = var.cloudfront_distribution_trusted_key_groups

  # Set up a trusted signer
  trusted_signers = var.cloudfront_distribution_trusted_signers
}

resource "aws_route53_zone" "video_streaming_zone" {
  name = var.route53_zone_name

  tags = var.route53_zone_tags
}

resource "aws_route53_record" "video_streaming_record" {
  name    = var.route53_record_name
  type    = var.route53_record_type
  zone_id = var.route53_record_zone_id

  alias {
    evaluate_target_health = true
    name                  = aws_cloudfront_distribution.video_streaming_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.video_streaming_distribution.hosted_zone_id
  }
}

resource "random_string" "bucket" {
  length = 8
}

resource "random_string" "logs" {
  length = 8
}
