    cidr_blocks = ["10.0.0.0/16"]
  }
  egress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }
}

resource "aws_lb" "example" {
  load_balancer_type = "application"
  subnets           = [aws_subnet.subnet_4.id, aws_subnet.subnet_5.id, aws_subnet.subnet_6.id]
  security_groups    = [aws_security_group.allow_inbound.id]
}

resource "aws_lb_target_group" "example_target_group" {
  vpc_id            = aws_vpc.main.id
  port              = 80
  protocol          = "HTTP"
  health_check {
    port     = 80
    protocol = "HTTP"
  }
}

resource "aws_lb_listener" "example_listener" {
  load_balancer_arn = aws_lb.example.id
  port              = 80
  protocol          = "TCP"
  default_action {
    target_group_arn = aws_lb_target_group.example_target_group.id
    type             = "forward"
  }
}

resource "aws_lb_target_group_attachment" "example_attachment" {
  target_group_arn = aws_lb_target_group.example_target_group.id
  target_id       = aws_instance.example.id
}

resource "aws_instance" "example" {
  ami           = "ami-0c55b159cbfafe1f0"  # Latest Ubuntu 20.04 AMI
  instance_type = "t3.micro"
  subnet_id      = aws_subnet.subnet_4.id
  key_name       = "my-key-pair"  # Replace with your existing key pair name
  security_groups = [aws_security_group.allow_inbound.id]
}

resource "aws_route53_zone" "test_video_stream_com" {
  name = "test-video-stream.com"
}

resource "aws_route53_record" "lb_alias_ipv4" {
  zone_id     = aws_route53_zone.test_video_stream_com.zone_id
  name        = "lb"
  type        = "A"
  alias {
    evaluate_target_health = true
    name                  = aws_lb.example.dns_name
    zone_id                = aws_lb.example.zone_id
  }
}

resource "aws_route53_record" "lb_alias_ipv6" {
  zone_id     = aws_route53_zone.test_video_stream_com.zone_id
  name        = "lb"
  type        = "AAAA"
  alias {
    evaluate_target_health = true
    name                  = aws_lb.example.dns_name
    zone_id                = aws_lb.example.zone_id
  }
}
