provider "aws" {
  region = "us-west-2"  # Example region, replace with your desired region
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Security group for PostgreSQL database"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_parameter_group" "pg_param_group" {
  family = "postgres15"
  name   = "pg-param-group"

  parameter {
    name         = "max_connections"
    value        = "100"
    apply_method = "immediate"
  }

  parameter {
    name         = "shared_buffers"
    value        = "256MB"
    apply_method = "immediate"
  }
}

resource "aws_db_instance" "db_instance" {
  instance_class = "db.t3.micro"
  allocated_storage = 50
  engine          = "postgres"
  engine_version = "15.0"
  db_subnet_group_name = "default"
  vpc_security_group_ids = [aws_security_group.db_sg.id]
  parameter_group_name = aws_db_parameter_group.pg_param_group.name
  storage_encrypted = true
  kms_key_id = aws_kms_key.db_kms_key.arn
  multi_az = true
  backup_retention_period = 7
  backup_window = "07:00-09:00"
  auto_minor_version_upgrade = true
}

resource "aws_kms_key" "db_kms_key" {
  description = "KMS key for encrypting database backups"
  deletion_window_in_days = 7
}

resource "aws_s3_bucket" "db_backup_bucket" {
  bucket = "db-backup-bucket-${var.environment}"
  acl = "private"
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.db_kms_key.arn
        sse_algorithm = "aws:kms"
      }
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "db_backup_bucket_encryption" {
  bucket = aws_s3_bucket.db_backup_bucket.bucket
}

variable "environment" {
  description = "Environment identifier for the S3 bucket"
  default     = "dev"
}
```

