provider "aws" {
  region = "us-west-2"  # Example region, replace with your desired region
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  instance_tenancy = "default"
  tags = {
    Name = "PostgreSQL-VPC"
  }
}

# Create two subnets
resource "aws_subnet" "subnet1" {
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "PostgreSQL-Subnet1"
  }
}

resource "aws_subnet" "subnet2" {
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "PostgreSQL-Subnet2"
  }
}

# Create a security group
resource "aws_security_group" "db_sg" {
  vpc_id = aws_vpc.main.id
  description = "Allow inbound PostgreSQL traffic"
  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "PostgreSQL-Security-Group"
  }
}

# Create a parameter group
resource "aws_db_parameter_group" "pg_param_group" {
  family = "postgres13"
  description = "Custom parameter group for PostgreSQL"
  parameter {
    name        = "max_connections"
    value       = "100"
    apply_method = "immediate"
  }
  parameter {
    name        = "work_mem"
    value       = "128MB"
    apply_method = "immediate"
  }
  tags = {
    Name = "PostgreSQL-Parameter-Group"
  }
}

# Create a KMS key
resource "aws_kms_key" "db_kms_key" {
  description = "KMS key for PostgreSQL encryption"
  tags = {
    Name = "PostgreSQL-KMS-Key"
  }
}

# Create a database instance
resource "aws_db_instance" "db_instance" {
  engine              = "postgres"
  engine_version      = "13.6"
  instance_class      = "db.t3.micro"
  allocated_storage   = 20
  storage_type        = "gp2"
  db_subnet_group_name = aws_db_subnet.subnet1.name
  vpc_security_group_ids = [aws_security_group.db_sg.id]
  parameter_group_name = aws_db_parameter_group.pg_param_group.name
  kms_key_id           = aws_kms_key.db_kms_key.arn
  backup_retention_period = 7
  tags = {
    Name = "PostgreSQL-DB-Instance"
  }
}
```

