```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_instance_name" {
  default = "my-postgres-db"
}

variable "db_instance_class" {
  default = "db.t4g.micro"
}

variable "db_instance_allocated_storage" {
  default = 200
}

variable "db_instance_backup_retention_period" {
  default = 7
}

variable "db_instance_backup_window" {
  default = "07:00-09:00"
}

variable "db_instance_engine_version" {
  default = "15.3"
}

variable "db_instance_storage_type" {
  default = "gp2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet1" {
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet2" {
  vpc_id = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "db_sg" {
  name = "db-sg"
  description = "Allow database access"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name = var.db_instance_name
  subnet_ids = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]
}

resource "aws_db_instance" "db_instance" {
  instance_class = var.db_instance_class
  allocated_storage = var.db_instance_allocated_storage
  engine = "postgres"
  engine_version = var.db_instance_engine_version
  storage_type = var.db_instance_storage_type
  db_name = var.db_instance_name
  username = "admin"
  password = "securepassword123"
