  instance_tenancy = "default"
}

resource "aws_subnet" "subnet" {
  count = 2
  vpc_id = aws_vpc.vpc.id
  cidr_block = cidrsubnet(aws_vpc.vpc.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]
}

resource "aws_security_group" "sg" {
  vpc_id = aws_vpc.vpc.id
  description = "Allow inbound MySQL traffic"
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "iam_role" {
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_secretsmanager_secret" "secret" {
  name = "my-rds-secret"

  description = "Secret containing RDS credentials"

  secret_string = jsonencode({
    username = "admin"
    password = "securepassword123"
  })
}

resource "aws_rds_cluster" "cluster" {
  engine = "aurora-mysql"
  engine_version = "5.7.mysql_aurora.2.07.1"
  master_username = "admin"
  master_password = var.master_password
  db_subnet_group_name = aws_db_subnet_group.db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.sg.id]
  iam_roles = [aws_iam_role.iam_role.arn]
  cluster_identifier = "my-rds-cluster"
  backup_retention_period = 7
  preferred_backup_window = "03:00-04:00"
  preferred_maintenance_window = "05:00-06:00"
  skip_final_snapshot = true
  secrets_manager_secret_arn = aws_secretsmanager_secret.secret.arn
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name = "my-rds-subnet-group"
  subnet_ids = aws_subnet.subnet.*.id
}

resource "aws_rds_proxy" "proxy" {
  db_cluster_identifier = aws_rds_cluster.cluster.id
  vpc_subnet_ids = aws_subnet.subnet.*.id
  auth {
    username = "admin"
    secret_arn = aws_secretsmanager_secret.secret.arn
  }
  idle_client_timeout = 1800
  debug_logging = false
}
