### Description
This Terraform program manages an AWS Lightsail Distribution with a bucket as its origin. The distribution is configured with basic caching settings and default behavior.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket"
  default     = "example-bucket-${random_string.random_suffix.result}"
}

variable "bucket_region" {
  description = "Region of the S3 bucket"
  default     = "us-east-1"
}

resource "aws_s3_bucket" "example" {
  bucket = var.bucket_name
  region = var.bucket_region

  tags = {
    Name = "ExampleBucket"
  }
}

resource "aws_lightsail_distribution" "example" {
  name        = "example-distribution"
  bundle_id   = "small_1_0"
  origin {
    name        = aws_s3_bucket.example.bucket
    region_name = aws_s3_bucket.example.region
  }
  default_cache_behavior {
    behavior = "cache"
  }
  cache_behavior_settings {
    allowed_http_methods = ["GET", "HEAD", "OPTIONS", "PUT", "PATCH", "POST", "DELETE"]
    cached_http_methods = ["GET", "HEAD"]
    default_ttl         = 86400
    maximum_ttl         = 31536000
    minimum_ttl         = 0
    forwarded_cookies {
      option = "none"
    }
    forwarded_headers {
      option = "default"
    }
    forwarded_query_strings {
      option = false
    }
  }
}

resource "random_string" "random_suffix" {
  length = 8
  special = false
}
```

### Explanation
- **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region.
- **Variables**: Two variables, `bucket_name` and `bucket_region`, are defined with default values. These allow for flexibility in naming and region selection.
- **S3 Bucket**: An S3 bucket is created with the specified name and region, and it is tagged with "ExampleBucket".
- **Lightsail Distribution**: A Lightsail distribution is set up with the specified bundle ID, using the S3 bucket as its origin. Basic caching settings are applied.
- **Random String**: A random suffix is generated to ensure unique bucket names across runs.

