```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_glacier_vault" "my_glacier_vault" {
  name = "my-glacier-vault"

  access_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = "*"
        Action = ["glacier:ListVaults", "glacier:GetVaultAccessPolicy", "glacier:SetVaultAccessPolicy"]
        Resource = "arn:aws:glacier:us-east-1:${var.account_id}:vaults/my-glacier-vault"
      }
    ]
  })

  tags = {
    Name = "My Glacier Vault"
  }
}

data "aws_iam_policy_document" "my_glacier_access_policy" {
  statement {
    sid = "AllowAccessToVault"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = ["arn:aws:iam::${var.account_id}:root"]
    }
    actions = ["glacier:*"]
    resources = ["arn:aws:glacier:us-east-1:${var.account_id}:vaults/my-glacier-vault"]
  }
}

variable "account_id" {
  default = "123456789012"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region.
- **Glacier Vault**: An S3 Glacier Vault named `my-glacier-vault` is created.
- **Access Policy**: A custom access policy is defined using a JSON string. It allows the root user to perform all Glacier operations on the vault.
- **IAM Policy Document**: A data source `aws_iam_policy_document` is used to define the access policy in a structured way.
- **Variables**: The `account_id` variable is provided with a default value to ensure the Terraform script can be run offline without errors.

