```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vault_name" {
  description = "Name of the Glacier vault"
  default     = "example-glacier-vault"
}

variable "policy" {
  description = "Policy for the Glacier vault lock"
  default     = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Deny"
        Principal = "*"
        Action   = "glacier:DeleteArchive"
        Resource = aws_glacier_vault.vault_name.arn
        Condition = {
          NumericLessThanEquals = {
            glacier:ArchiveAgeinDays = 365
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket" "example_s3_bucket" {
  bucket = "example-s3-bucket-${random_string.random_suffix.result}"
  acl    = "private"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_glacier_vault" "vault" {
  name = var.vault_name

  depends_on = [aws_s3_bucket.example_s3_bucket]
}

resource "aws_glacier_vault_lock" "lock" {
  complete_lock = false
  policy        = var.policy
  vault_name    = aws_glacier_vault.vault.name
}
```

