variable "subnets" {
  description = "List of subnet IDs where the load balancer will be deployed"
  type        = list(string)
  default     = aws_subnet.public[*].id
}

variable "security_group_id" {
  description = "ID of the security group for the load balancer"
  type        = string
  default     = aws_security_group.lb_sg.id
}

variable "load_balancer_type" {
  description = "Type of load balancer (e.g., application, network)"
  type        = string
  default     = "application"
}

variable "enable_deletion_protection" {
  description = "Enable deletion protection for the load balancer"
  type        = bool
  default     = true
}

variable "access_logs_bucket" {
  description = "S3 bucket for access logs"
  type        = string
  default     = aws_s3_bucket.lb_logs.bucket
}

variable "access_logs_enabled" {
  description = "Enable access logs"
  type        = bool
  default     = true
}

variable "access_logs_prefix" {
  description = "Prefix for access logs"
  type        = string
  default     = "gateway-lb"
}

resource "aws_lb" "gateway_lb" {
  name               = "gateway-lb"
  internal           = false
  load_balancer_type = var.load_balancer_type
  security_groups    = [var.security_group_id]
  subnets            = var.subnets
  enable_deletion_protection = var.enable_deletion_protection

  access_logs {
    bucket = var.access_logs_bucket
    enabled = var.access_logs_enabled
    prefix = var.access_logs_prefix
  }

  tags = {
    Environment = "production"
  }
}
