  name        = "lb-sg"
  description = "Allow inbound HTTP and HTTPS traffic"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "app_sg" {
  name        = "app-sg"
  description = "Allow inbound HTTP traffic"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "lambda_load_balancer" {
  name               = "lambda-load-balancer"
  internal            = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.lb_sg.id]
  subnets             = aws_subnet.public[*].id
  enable_deletion_protection = true
  access_logs {
    bucket = aws_s3_bucket.lb_logs.id
    prefix = "lambda-load-balancer"
    enabled = true
  }
  tags = {
    Environment = "production"
  }
}

resource "aws_lambda_function" "lambda_function" {
  function_name = "lambda-function"
  role          = aws_iam_role.lambda_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  code {
    s3_bucket = aws_s3_bucket.lambda_code.id
    s3_key    = "lambda_function.zip"
  }
  vpc_config {
    subnet_ids = aws_subnet.public[*].id
    security_group_ids = [aws_security_group.app_sg.id]
  }
  depends_on = [aws_s3_bucket.lambda_code]
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_role.name
}

resource "aws_s3_bucket" "lb_logs" {
  bucket = "lambda-load-balancer-logs"
  acl    = "private"
}

resource "aws_s3_bucket" "lambda_code" {
  bucket = "lambda-function-code"
  acl    = "private"
}

resource "aws_s3_object" "lambda_function_zip" {
  bucket = aws_s3_bucket.lambda_code.bucket
  key    = "lambda_function.zip"
  source = "path/to/your/lambda_function.zip"
}
