```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "assign_generated_ipv6_cidr_block" {
  description = "Assign a generated IPv6 CIDR block to the VPC"
  type        = bool
  default     = true
}

resource "aws_vpc" "pike_vpc" {
  cidr_block = var.vpc_cidr_block
  assign_generated_ipv6_cidr_block = var.assign_generated_ipv6_cidr_block
  tags = {
    Name = "pike_vpc"
    permissions = "allow-ipv6"
  }
}

resource "aws_egress_only_internet_gateway" "pike_egress_only_internet_gateway" {
  vpc_id = aws_vpc.pike_vpc.id
  tags = {
    Name = "pike_egress_only_internet_gateway"
    permissions = "allow-ipv6"
  }
}

resource "aws_security_group" "pike_sg" {
  vpc_id = aws_vpc.pike_vpc.id
  name = "pike_sg"
  description = "Allow outbound traffic"
  ingress {
    cidr_blocks = ["0.0.0.0/0"]
    from_port = 0
    to_port = 65535
    protocol = "-1"
  }
  egress {
    cidr_blocks = ["0.0.0.0/0", "::/0"]
    from_port = 0
    to_port = 65535
    protocol = "-1"
  }
}
